      const captions = Array.from({ length: photos.length }, (_, i) => (p.studentGrid.captions || [])[i] || '');
      const [removedPhoto] = photos.splice(from, 1);
      photos.splice(to, 0, removedPhoto);
      const [removedCaption] = captions.splice(from, 1);
