  // Switch Theme Preset
  const applyThemePreset = (themeKey: string) => {
    const thm = THEMES[themeKey];
    if (!thm) return;
    triggerSimulatorSkeleton(380);
    setData(p => ({
      ...p,
      theme: themeKey,
      customColors: { ...p.customColors, enabled: false },
      styling: {
        ...p.styling,
        fontFamily: thm.fontHeadline,
      }
    }));
  };

